import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { CompanyService } from 'src/app/service/company/company.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent implements OnInit {

  company!: Company;

  // Editable form fields, kept separate from the loaded model until saved.
  companyName = '';
  website = '';
  location = '';
  description = '';

  saving = false;

  constructor(
    private compService: CompanyService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getCompanyById();
  }

  getCompanyById() {
    this.compService.getCompanyById(Number(localStorage.getItem('id')))
      .subscribe(res => {
        this.company = res;
        this.companyName = res.companyName || '';
        this.website = res.website || '';
        this.location = res.location || '';
        this.description = res.description || '';
      });
  }

  save(): void {
    const id = Number(localStorage.getItem('id'));
    const updated: Partial<Company> = {
      companyName: this.companyName,
      website: this.website,
      location: this.location,
      description: this.description
    };

    this.saving = true;
    this.compService.updateCompany(id, updated).subscribe({
      next: () => {
        this.saving = false;
        this.router.navigateByUrl('/company/profile-company');
      },
      error: (err) => {
        this.saving = false;
        console.log(err);
        alert('Could not save changes. Please try again.');
      }
    });
  }
}
<div class="page">
<app-header variant="company"></app-header>
<div class="app-shell">
<app-sidebar variant="company"></app-sidebar>
<main class="main">

<div class="page-title">Edit Company Profile</div>
<div class="form-card">
  <div class="field"><label>Company name</label><input [(ngModel)]="companyName" name="companyName"></div>
  <div class="field"><label>Website</label><input [(ngModel)]="website" name="website"></div>
  <div class="field"><label>Location</label><input [(ngModel)]="location" name="location"></div>
  <div class="field"><label>Description</label><textarea [(ngModel)]="description" name="description"></textarea></div>
  <div class="form-actions">
    <button class="btn btn-primary" [disabled]="saving" (click)="save()">{{ saving ? 'Saving…' : 'Save changes' }}</button>
    <a routerLink="/company/profile-company" class="btn btn-secondary">Cancel</a>
  </div>
</div>

</main>
</div>
</div>
